pub fn get_block_type<B: ?Sized + 'static>(key: &str) -> JRef<B> {
    // Cast instead of using BlockType#typed, since block type can be a mock during testing and would return null
    let block_type = registry::BLOCK.get_or_throw(
        // PORT: adventure's Key.key(String namespace, String value); its Rust name comes with the adventure port
    akey::key_2(akey::MINECRAFT_NAMESPACE, key),
    );
    cast::<B, _>(&block_type).unwrap_or_else(|| panic!("ClassCastException: block type {} is not a {}", key, std::any::type_name::<B>()))
} // paper-api/src/main/java/org/bukkit/block/BlockType.java:2772
